  transientRetryNotice?.call(
    attempt,
    maxAttempts,
    survived ? delay : Duration.zero,
    reason,
  );
  if (survived) return true;
  if (cancelToken?.cancelReason is RunIdleWatchdogFire) {
    cancelToken?.reset();
    return true;
  }
  _pushAborted(out, model, lastFailure, resume: resume);
  return false;
}

